package ai.unifiedprocess.petclinic.vet.domain;

import org.jooq.DSLContext;
import org.jooq.Record1;
import org.jooq.impl.DSL;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

import java.util.stream.Stream;

import static ai.unifiedprocess.demo.petclinic.database.Tables.SPECIALTIES;
import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
import static org.jooq.Records.mapping;
import static org.jooq.impl.DSL.multiset;

/** Read queries for the veterinarian directory (UC-002). */
@Repository
@Transactional(readOnly = true)
public class VetRepository {

    private final DSLContext dsl;

    public VetRepository(DSLContext dsl) {
        this.dsl = dsl;
    }

    public Stream<Vet> findPage(int offset, int limit) {
        return dsl.select(
                        VETS.ID,
                        VETS.FIRST_NAME,
                        VETS.LAST_NAME,
                        multiset(DSL.select(SPECIALTIES.NAME)
                                .from(VET_SPECIALTIES)
                                .join(SPECIALTIES).on(SPECIALTIES.ID.eq(VET_SPECIALTIES.SPECIALTY_ID))
                                .where(VET_SPECIALTIES.VET_ID.eq(VETS.ID))
                                .orderBy(SPECIALTIES.NAME.asc()))
                                .as("specialties")
                                .convertFrom(rows -> rows.map(Record1::value1)))
                .from(VETS)
                .orderBy(VETS.ID.asc())
                .limit(limit)
                .offset(offset)
                .fetch(mapping(Vet::new))
                .stream();
    }

    public int count() {
        return dsl.fetchCount(VETS);
    }
}
package ai.unifiedprocess.petclinic.vet.ui;

import ai.unifiedprocess.petclinic.core.ui.MainLayout;
import ai.unifiedprocess.petclinic.vet.domain.Vet;
import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
import com.vaadin.flow.component.grid.Grid;
import com.vaadin.flow.component.html.H2;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.router.PageTitle;
import com.vaadin.flow.router.Route;
import com.vaadin.flow.theme.lumo.LumoUtility;

/** UC-002: View Veterinarians. */
@Route(value = "vets", layout = MainLayout.class)
@PageTitle("Veterinarians")
public class VeterinariansView extends VerticalLayout {

    private final transient VetRepository vetRepository;

    public VeterinariansView(VetRepository vetRepository) {
        this.vetRepository = vetRepository;
        addClassNames(LumoUtility.Padding.MEDIUM);

        H2 heading = new H2("Veterinarians");
        heading.addClassNames(LumoUtility.Margin.NONE);

        Grid<Vet> grid = new Grid<>(Vet.class, false);
        grid.setId("veterinarians-grid");
        grid.addColumn(Vet::firstName).setHeader("First name").setAutoWidth(true);
        grid.addColumn(Vet::lastName).setHeader("Last name").setAutoWidth(true);
        grid.addColumn(vet -> vet.specialties().isEmpty()
                        ? "none"
                        : String.join(", ", vet.specialties()))
                .setHeader("Specialties").setAutoWidth(true).setFlexGrow(1);
        grid.setItems(query -> this.vetRepository.findPage(query.getOffset(), query.getLimit()),
                query -> this.vetRepository.count());
        grid.setWidthFull();

        add(heading, grid);
    }
}
